void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
struct Sandbox {juce::File path=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("gboy-library-test-"+juce::Uuid().toString());Sandbox(){check(path.createDirectory().wasOk(),"create sandbox");}~Sandbox(){path.deleteRecursively();}};
void wav(const juce::File& file){juce::WavAudioFormat format;auto stream=file.createOutputStream();check(stream!=nullptr,"sample output");std::unique_ptr<juce::AudioFormatWriter> writer(format.createWriterFor(stream.get(),48000,1,16,{},0));check(writer!=nullptr,"sample writer");stream.release();juce::AudioBuffer<float> buffer(1,48000);for(int i=0;i<48000;++i)buffer.setSample(0,i,float(.5*std::sin(gboy::tau*220*i/48000)));check(writer->writeFromAudioSampleBuffer(buffer,0,48000),"write sample");}
void idle(gboy::library::LibraryManager& library){check(library.waitUntilIdle(),"library worker timeout");}
void settle(GBoyProcessor& p){juce::AudioBuffer<float> buffer(2,128);juce::MidiBuffer midi;for(int n=0;n<3000;++n){p.processBlock(buffer,midi);bool loading=false;for(int i=0;i<4;++i)loading|=p.isBusy(i);if(!loading)return;std::this_thread::sleep_for(std::chrono::milliseconds(10));}throw std::runtime_error("sample loader timeout");}
int main(){try{juce::ScopedJuceInitialiser_GUI gui;Sandbox sandbox;const auto source=sandbox.path.getChildFile("source");source.createDirectory();const auto tone=source.getChildFile(juce::String::fromUTF8("Étoile A3.wav"));wav(tone);const auto home=sandbox.path.getChildFile("profile");juce::String sampleId,linkedId;
 {
 gboy::library::LibraryManager library(home);idle(library);check(library.snapshot().entries.size()==29,"29 real factory entries");gboy::library::Query query;query.text="bedroom haze";check(gboy::library::search(library.snapshot(),query).size()==1,"all-token factory search");library.importFiles({tone,source.getChildFile("missing.wav")});idle(library);query={};query.kind="sample";auto entries=gboy::library::search(library.snapshot(),query);auto sample=std::find_if(entries.begin(),entries.end(),[](const auto& e){return e.action=="file";});check(sample!=entries.end()&&sample->analysed&&sample->root==57,"import copies, decodes and detects root");sampleId=sample->id;check(juce::File(sample->path).existsAsFile()&&sample->path!=tone.getFullPathName(),"managed import copy");library.edit(sampleId,"WORLD","French, intimate, test", "Test Performer","CC0-1.0","Original test oscillator, synthetic",57);library.favorite(sampleId,true);idle(library);query={};query.text="french test performer";query.favorites=true;check(gboy::library::search(library.snapshot(),query).size()==1,"metadata search and favorite filter");
 library.scanFolder(source);idle(library);for(const auto& root:library.snapshot().roots)if(root.id.startsWith("folder-"))linkedId=root.id;check(linkedId.isNotEmpty(),"linked folder index");const auto moved=sandbox.path.getChildFile("moved");check(source.moveFileTo(moved),"move linked folder");library.rescan();idle(library);bool missing=false;for(const auto& e:library.snapshot().entries)if(e.libraryId==linkedId)missing=e.missing;check(missing,"missing files retained and marked");library.relocate(linkedId,moved);idle(library);for(const auto& e:library.snapshot().entries)if(e.libraryId==linkedId)check(!e.missing&&juce::File(e.path).existsAsFile(),"relocation recovers stable IDs");
 const auto pack=sandbox.path.getChildFile("exported");library.exportLibrary("user",pack);idle(library);check(pack.getChildFile("gboy-library.json").existsAsFile(),"export user content with provenance");library.installPack(pack);idle(library);check(library.snapshot().roots.size()==3,"install pack registers copied root");const auto count=library.snapshot().entries.size();library.installPack(pack);idle(library);check(library.snapshot().entries.size()==count&&library.snapshot().status.containsIgnoreCase("already installed"),"duplicate install rejected without mutation");
 // Reject traversal before any staging copy or index mutation.
 auto manifest=juce::JSON::parse(pack.getChildFile("gboy-library.json").loadFileAsString());manifest.getDynamicObject()->setProperty("id","malicious-pack");manifest["entries"].getArray()->getReference(0).getDynamicObject()->setProperty("file","../outside.wav");const auto bad=sandbox.path.getChildFile("bad-pack");bad.createDirectory();bad.getChildFile("gboy-library.json").replaceWithText(juce::JSON::toString(manifest));library.installPack(bad);idle(library);check(library.snapshot().entries.size()==count&&library.snapshot().status.containsIgnoreCase("safe existing file"),"manifest traversal rejected");
 }
 {gboy::library::LibraryManager restored(home);idle(restored);check(restored.find(sampleId).favorite&&restored.find(sampleId).tags.contains("French"),"favorites and edited metadata persist");}
 // Processor integration: browse/load, preview without patch changes, relocated project recall.
 auto p=std::make_unique<GBoyProcessor>(sandbox.path.getChildFile("processor-profile"));p->prepareToPlay(48000,256);idle(p->library);p->library.scanFolder(sandbox.path.getChildFile("moved"));idle(p->library);gboy::library::Entry asset;for(const auto& e:p->library.snapshot().entries)if(e.action=="file")asset=e;check(asset.id.isNotEmpty()&&p->loadLibraryEntry(asset.id,0),"load indexed asset");settle(*p);juce::MemoryBlock state;p->getStateInformation(state);auto xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),int(state.getSize()));check(xml&&xml->getStringAttribute("sampleAsset1")==asset.id&&xml->getIntAttribute("sampleRoot1")==57,"project stores stable ID and root");
 const auto before=p->state.getRawParameterValue("l1_generator")->load();p->previewLibraryEntry("factory:hybrid:4");for(int n=0;n<3000&&p->previewBusy.load();++n)std::this_thread::sleep_for(std::chrono::milliseconds(10));check(!p->previewBusy.load(),"factory preview completed");juce::AudioBuffer<float> audio(2,256);juce::MidiBuffer midi;double energy=0;for(int i=0;i<100;++i){p->processBlock(audio,midi);energy+=audio.getMagnitude(0,256);}check(energy>0&&p->state.getRawParameterValue("l1_generator")->load()==before,"separate preview audible without patch mutation");p->setNonRealtime(true);p->processBlock(audio,midi);check(audio.getMagnitude(0,256)==0,"offline bounce excludes active browser preview");p->setNonRealtime(false);p->processBlock(audio,midi);check(audio.getMagnitude(0,256)==0,"offline cancellation does not resume an old audition");p->stopLibraryPreview();
 const auto relocated=sandbox.path.getChildFile("relocated-again");check(sandbox.path.getChildFile("moved").moveFileTo(relocated),"move processor library");p->library.relocate(asset.libraryId,relocated);idle(p->library);p->setStateInformation(state.getData(),int(state.getSize()));settle(*p);check(p->status(0)==juce::File(asset.path).getFileName(),"stable library ID recovers project sample after relocation");p->getStateInformation(state);xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),int(state.getSize()));check(xml->getStringAttribute("sampleSource1").startsWith(relocated.getFullPathName()),"recall records recovered source path");

 // Bundle a full patch and its managed sample, then bind relative references to installed IDs.
 p->library.importFiles({relocated.getChildFile(juce::File(asset.path).getFileName())});idle(p->library);gboy::library::Entry managed;for(const auto& e:p->library.snapshot().entries)if(e.libraryId=="user"&&e.kind=="sample")managed=e;check(p->loadLibraryEntry(managed.id,0),"load managed sample for portable patch");settle(*p);check(p->saveLibraryPatch(sandbox.path.getChildFile("Portable.gboy")),"save patch to browser");idle(p->library);auto* volume=p->state.getParameter("volume");volume->setValueNotifyingHost(volume->convertTo0to1(.27f));check(p->saveLibraryPatch(sandbox.path.getChildFile("Portable.gboy")),"overwrite saved patch");idle(p->library);gboy::library::Entry savedPatch;for(const auto& e:p->library.snapshot().entries)if(e.libraryId=="user"&&e.kind=="patch")savedPatch=e;volume->setValueNotifyingHost(volume->convertTo0to1(.8f));check(p->loadLibraryEntry(savedPatch.id,0),"reload overwritten managed patch");settle(*p);check(std::abs(p->state.getRawParameterValue("volume")->load()-.27f)<.0002f,"re-import refreshes managed patch instead of keeping stale bytes");for(const auto& e:p->library.snapshot().entries)if(e.libraryId=="user")p->library.edit(e.id,e.category,e.tags,"G Boy test","CC0-1.0","Original synthetic test content",e.root);idle(p->library);const auto portable=sandbox.path.getChildFile("portable");p->library.exportLibrary("user",portable);idle(p->library);check(portable.getChildFile("gboy-library.json").existsAsFile(),"portable sample+patch export");p->library.installPack(portable);idle(p->library);gboy::library::Entry installedPatch;for(const auto& e:p->library.snapshot().entries)if(e.kind=="patch"&&e.libraryId.startsWith("pack-"))installedPatch=e;check(installedPatch.id.isNotEmpty()&&p->loadLibraryEntry(installedPatch.id,0),"load installed portable patch");settle(*p);p->getStateInformation(state);xml=juce::AudioProcessor::getXmlFromBinary(state.getData(),int(state.getSize()));check(xml->getStringAttribute("sampleAsset1").startsWith(installedPatch.libraryId+":"),"portable patch resolves installed sample identity");
 std::cout<<"PASS library: search, Unicode import/analysis, favorites/metadata persistence, linked folders, missing/relocate, pack export/install, duplicate/traversal rejection, processor load/root/preview/relocated recall\n";
 }catch(const std::exception& e){std::cerr<<"FAIL library: "<<e.what()<<std::endl;return 1;}}
